    sort(order.begin(), order.end(), [&](int a, int b) {
        return (long long)(fix[a] + walk) * line[b] < (long long)(fix[b] + walk) * line[a];
    });

    long long now = 0;  // 지금 시각
    long long total = 0;  // 기다림의 합 (int를 넘을 수 있다)
    for (int k = 0; k < n; k++) {
        int ride = order[k];
        if (k > 0) {
            now += walk;  // 다음 놀이기구까지 걸어간다(첫 놀이기구는 걷지 않는다)
        }
