from collections import deque


def solution(building):
    rows = len(building)
    cols = len(building[0])
    moves = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # 1. 불: 불이 난 칸을 모두 처음부터 큐에 넣고 한 번에 퍼뜨린다(여러 출발점 BFS)
    # fire[r][c]: 불이 (r, c)에 닿는 시각. -1은 불이 끝내 닿지 않는 칸
    fire = [[-1] * cols for _ in range(rows)]
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if building[r][c] == "F":
                fire[r][c] = 0
                queue.append((r, c))
            elif building[r][c] == "S":
                start_r, start_c = r, c
    while queue:
        r, c = queue.popleft()
        for dr, dc in moves:
