fn dijkstra(graph: &Vec<Vec<(usize, i64)>>, n: usize, start: usize) -> Vec<i64> {
    let mut dist = vec![INF; n + 1];
    dist[start] = 0;
    let mut heap = BinaryHeap::new();
    heap.push(Reverse((0i64, start)));
    while let Some(Reverse((d, now))) = heap.pop() {
