            for (long[] edge : graph.get(now)) {
                int nxt = (int) edge[0];
                if (d + edge[1] < dist[nxt]) {
                    dist[nxt] = d + edge[1];
                    heap.add(new long[]{dist[nxt], nxt});
                }
            }
