    let left = 1;
    let right = Math.min(...chargers) * n;
    while (left < right) {
        // (left + right) >> 1 은 32비트로 잘려 무한 반복이 되니, 나눗셈과 내림을 쓴다
        const mid = Math.floor((left + right) / 2);
        let done = 0;
        for (const minute of chargers) {
            done += Math.floor(mid / minute);
        }
        if (done >= n) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}

