    private String find(Map<String, String> parent, String x) {
        if (!parent.containsKey(x)) parent.put(x, x);
        while (!parent.get(x).equals(x)) {
            parent.put(x, parent.get(parent.get(x))); // 경로 압축
            x = parent.get(x);
        }
        return x;
    }
