using namespace std;

// 할증 시간: 07:30 이상 09:30 미만, 17:00 이상 19:00 미만(분)
const int RUSH[2][2] = {{7 * 60 + 30, 9 * 60 + 30}, {17 * 60, 19 * 60}};

